create or replace function app.guard_admin_change() returns trigger language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());super_admin_role uuid;remaining integer;begin select id into super_admin_role from public.roles where key='super_admin';if actor is not null and tg_op='UPDATE' then if new.id=actor and new.role_id is distinct from old.role_id then raise exception 'You cannot change your own role.' using errcode='42501';end if;if new.id=actor and old.is_active and not new.is_active then raise exception 'You cannot disable your own account.' using errcode='42501';end if;if (new.role_id is distinct from old.role_id or new.is_active is distinct from old.is_active) and not app.is_active_super_admin() then raise exception 'Only an active Super Admin may change admin role or activation status.' using errcode='42501';end if;if new.role_id is distinct from old.role_id then perform app.assert_role_assignable(new.role_id);end if;end if;if actor is not null and tg_op='INSERT' then if not app.is_active_super_admin() then raise exception 'Only an active Super Admin may create admin assignments.' using errcode='42501';end if;perform app.assert_role_assignable(new.role_id);end if;if tg_op='UPDATE' and old.role_id=super_admin_role and (new.role_id is distinct from old.role_id or (old.is_active and not new.is_active)) then select count(*) into remaining from public.admins a join public.user_accounts ua on ua.id=a.id where a.role_id=super_admin_role and a.is_active and ua.status='active' and a.id<>old.id;if remaining=0 then raise exception 'The last active Super Admin cannot be disabled or demoted.' using errcode='42501';end if;end if;return new;end$$;
create or replace function app.guard_role_permission_change() returns trigger language plpgsql security definer set search_path='' as $$declare actor uuid:=(select auth.uid());actor_role uuid;target_role uuid:=coalesce(new.role_id,old.role_id);target_permission uuid:=coalesce(new.permission_id,old.permission_id);permission_key text;target_is_system boolean;begin if actor is null then return coalesce(new,old);end if;select a.role_id into actor_role from public.admins a where a.id=actor;select r.is_system into target_is_system from public.roles r where r.id=target_role;if target_is_system and not app.is_active_super_admin() then raise exception 'Only an active Super Admin may modify system role permissions.' using errcode='42501';end if;if actor_role=target_role then raise exception 'You cannot modify the permissions of your own role.' using errcode='42501';end if;select p.key into permission_key from public.permissions p where p.id=target_permission;if not app.has_permission(permission_key) then raise exception 'You cannot assign a permission you do not hold: %',permission_key using errcode='42501';end if;update public.roles set permission_version=permission_version+1 where id=target_role;return coalesce(new,old);end$$;